  ('e437a873-424a-9320-6916-e05053f9a0fe'::uuid, 'batch18_characters_probe_zeruiah_three_sons_mcq_v1', 'batch18|1CH|zeruiah_three_sons', '{"prompt": "Joab, Abishai, and Asahel were the three sons of which woman?", "choices": [{"id": "A", "text": "Zeruiah"}, {"id": "B", "text": "Abigail", "meta": {"distractor": {"plausibility": "high", "misconception_code": "sister_of_zeruiah_confused_for_her", "relation": "same_generation"}}}, {"id": "C", "text": "Ahinoam", "meta": {"distractor": {"plausibility": "high", "misconception_code": "davids_wife_confused_for_his_sister", "relation": "same_generation"}}}, {"id": "D", "text": "Bathsheba", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "most_famous_woman_of_davids_court", "relation": "same_generation"}}}], "correct_choice_id": "A", "correct_answer": "Zeruiah", "explanation": "1 Chronicles 2:16 names Zeruiah and Abigail as sisters, and lists Zeruiah''s sons as Abishai, Joab, and Asahel. Zeruiah''s name, not their father''s, identifies these three throughout Samuel.", "book_code": "1CH", "chapter": 2, "reference": "1 Chronicles 2:16; 2 Samuel 2:18", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "e437a873-424a-9320-6916-e05053f9a0fe", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Zeruiah", "Abishai", "Asahel"], "stem_family": "characters|zeruiah", "difficulty_estimate": 610, "irt_b": 0.85, "importance_conceptual": 72, "importance_context": 78, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('4b800c27-bf0c-a883-5065-fbe39422d4da'::uuid, 'batch18_characters_probe_abishai_sauls_camp_mcq_v1', 'batch18|1SA|abishai_sauls_camp', '{"prompt": "When David asked who would go down with him into Saul''s camp by night, who answered, \"I will go with you\"?", "choices": [{"id": "A", "text": "Ahimelech the Hittite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_other_man_david_asked", "relation": "same_event"}}}, {"id": "B", "text": "Abishai son of Zeruiah"}, {"id": "C", "text": "Joab son of Zeruiah", "meta": {"distractor": {"plausibility": "high", "misconception_code": "more_famous_brother_assumed", "relation": "same_generation"}}}, {"id": "D", "text": "Asahel son of Zeruiah", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "third_brother_assumed", "relation": "same_generation"}}}], "correct_choice_id": "B", "correct_answer": "Abishai son of Zeruiah", "explanation": "David put the question to Ahimelech the Hittite and to Abishai son of Zeruiah, and it was Abishai who volunteered. Joab, the best known of the brothers, is not in the scene.", "book_code": "1SA", "chapter": 26, "reference": "1 Samuel 26:6", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "4b800c27-bf0c-a883-5065-fbe39422d4da", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Abishai"], "stem_family": "characters|abishai", "difficulty_estimate": 650, "irt_b": 1.0, "importance_conceptual": 68, "importance_context": 72, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('b8c92d0e-094c-42d6-45a6-4a645a1e36e5'::uuid, 'batch18_characters_probe_uzzah_ark_struck_mcq_v1', 'batch18|2SA|uzzah_ark_struck', '{"prompt": "Who took hold of the ark of God when the oxen stumbled, and was struck down on the spot?", "choices": [{"id": "A", "text": "Ahio son of Abinadab", "meta": {"distractor": {"plausibility": "high", "misconception_code": "brother_guiding_the_same_cart", "relation": "same_event"}}}, {"id": "B", "text": "Obed-edom the Gittite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "next_man_the_ark_is_given_to", "relation": "same_event"}}}, {"id": "C", "text": "Uzzah son of Abinadab"}, {"id": "D", "text": "Eleazar son of Abinadab", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "earlier_keeper_of_the_ark", "relation": "same_generation"}}}], "correct_choice_id": "C", "correct_answer": "Uzzah son of Abinadab", "explanation": "Uzzah and his brother Ahio were guiding the new cart. When the oxen stumbled Uzzah reached out to steady the ark and God struck him down, so David named the place Perez-uzzah.", "book_code": "2SA", "chapter": 6, "reference": "2 Samuel 6:6-7", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "b8c92d0e-094c-42d6-45a6-4a645a1e36e5", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Uzzah"], "stem_family": "characters|uzzah", "difficulty_estimate": 560, "irt_b": 0.6, "importance_conceptual": 74, "importance_context": 80, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('d924f7bd-e2ea-8cf6-bf02-1374f76c569d'::uuid, 'batch18_characters_probe_obed_edom_ark_house_mcq_v1', 'batch18|2SA|obed_edom_ark_house', '{"prompt": "In whose house did the ark stay three months, so that the LORD blessed him and all his household?", "choices": [{"id": "A", "text": "Abinadab of Kiriath-jearim", "meta": {"distractor": {"plausibility": "high", "misconception_code": "previous_house_that_held_the_ark", "relation": "same_event"}}}, {"id": "B", "text": "Ahimelech the Hittite", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "another_foreigner_in_davids_orbit", "relation": "same_role"}}}, {"id": "C", "text": "Ittai the Gittite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_other_famous_gittite", "relation": "same_role"}}}, {"id": "D", "text": "Obed-edom the Gittite"}], "correct_choice_id": "D", "correct_answer": "Obed-edom the Gittite", "explanation": "After Uzzah''s death David was unwilling to bring the ark on to the City of David, so he turned it aside to Obed-edom the Gittite. News of the blessing on that house is what moved David to complete the journey.", "book_code": "2SA", "chapter": 6, "reference": "2 Samuel 6:10-12", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "d924f7bd-e2ea-8cf6-bf02-1374f76c569d", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Obed-edom"], "stem_family": "characters|obed-edom", "difficulty_estimate": 640, "irt_b": 0.95, "importance_conceptual": 70, "importance_context": 76, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('3f65493a-35e2-fe4e-c93f-f97a5598967d'::uuid, 'batch18_characters_probe_benaiah_lion_pit_mcq_v1', 'batch18|2SA|benaiah_lion_pit', '{"prompt": "Which of David''s warriors went down into a pit on a snowy day and killed a lion?", "choices": [{"id": "A", "text": "Benaiah son of Jehoiada"}, {"id": "B", "text": "Eleazar son of Dodo the Ahohite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "adjacent_entry_in_the_same_list", "relation": "same_role"}}}, {"id": "C", "text": "Shammah son of Agee the Hararite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "adjacent_entry_in_the_same_list", "relation": "same_role"}}}, {"id": "D", "text": "Abishai son of Zeruiah", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "best_known_of_davids_warriors", "relation": "same_role"}}}], "correct_choice_id": "A", "correct_answer": "Benaiah son of Jehoiada", "explanation": "The roll of David''s mighty men credits Benaiah son of Jehoiada with striking down two champions of Moab and killing a lion in a pit on a snowy day. Eleazar and Shammah are neighbouring entries in the same list.", "book_code": "2SA", "chapter": 23, "reference": "2 Samuel 23:20", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "3f65493a-35e2-fe4e-c93f-f97a5598967d", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Benaiah"], "stem_family": "characters|benaiah", "difficulty_estimate": 690, "irt_b": 1.15, "importance_conceptual": 66, "importance_context": 70, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('fecd6779-76b7-ed89-e705-6dbc08c29567'::uuid, 'batch18_characters_probe_benaiah_over_army_mcq_v1', 'batch18|1KI|benaiah_over_army', '{"prompt": "After Joab was put to death, whom did Solomon appoint over the army in his place?", "choices": [{"id": "A", "text": "Amasa son of Ithra the Ishmaelite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "earlier_rival_commander_already_dead", "relation": "same_role"}}}, {"id": "B", "text": "Benaiah son of Jehoiada"}, {"id": "C", "text": "Abishai son of Zeruiah", "meta": {"distractor": {"plausibility": "high", "misconception_code": "joabs_brother_assumed_to_succeed", "relation": "same_role"}}}, {"id": "D", "text": "Adoniram son of Abda", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "another_named_officer_of_solomon", "relation": "same_role"}}}], "correct_choice_id": "B", "correct_answer": "Benaiah son of Jehoiada", "explanation": "Benaiah struck down Joab and was appointed in his place over the army, as Zadok was appointed in Abiathar''s place as priest. Amasa, whom Absalom had made commander, had already been killed by Joab.", "book_code": "1KI", "chapter": 2, "reference": "1 Kings 2:34-35", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "fecd6779-76b7-ed89-e705-6dbc08c29567", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Benaiah", "Amasa"], "stem_family": "characters|benaiah", "difficulty_estimate": 670, "irt_b": 1.05, "importance_conceptual": 68, "importance_context": 72, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('4263ea9a-86c1-8402-4cb6-e53483679e5b'::uuid, 'batch18_characters_probe_achish_gath_refuge_mcq_v1', 'batch18|1SA|achish_gath_refuge', '{"prompt": "David took his six hundred men and went over to which foreign king for refuge from Saul?", "choices": [{"id": "A", "text": "Nahash king of Ammon", "meta": {"distractor": {"plausibility": "high", "misconception_code": "another_foreign_king_in_samuel", "relation": "same_role"}}}, {"id": "B", "text": "Talmai king of Geshur", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_king_absalom_fled_to", "relation": "same_role"}}}, {"id": "C", "text": "Achish king of Gath"}, {"id": "D", "text": "Hanun king of Ammon", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "successor_of_nahash", "relation": "same_role"}}}], "correct_choice_id": "C", "correct_answer": "Achish king of Gath", "explanation": "David crossed to Achish son of Maoch, king of Gath, and lived in Philistine territory. Talmai of Geshur is the king Absalom later fled to; the Ammonite kings belong to David''s wars, not his exile.", "book_code": "1SA", "chapter": 27, "reference": "1 Samuel 27:2", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "4263ea9a-86c1-8402-4cb6-e53483679e5b", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Achish"], "stem_family": "characters|achish", "difficulty_estimate": 600, "irt_b": 0.8, "importance_conceptual": 70, "importance_context": 74, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('48532d53-96fd-af0c-27a0-9c44d281ccc6'::uuid, 'batch18_characters_probe_ziba_mephibosheth_mcq_v1', 'batch18|2SA|ziba_mephibosheth', '{"prompt": "Which servant of the house of Saul was summoned to tell David whether anyone of Saul''s line remained?", "choices": [{"id": "A", "text": "Shimei son of Gera", "meta": {"distractor": {"plausibility": "high", "misconception_code": "other_saul_clansman_who_meets_david", "relation": "same_book"}}}, {"id": "B", "text": "Machir son of Ammiel", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_man_who_had_sheltered_mephibosheth", "relation": "same_event"}}}, {"id": "C", "text": "Barzillai the Gileadite", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "another_man_who_serves_david", "relation": "same_book"}}}, {"id": "D", "text": "Ziba"}], "correct_choice_id": "D", "correct_answer": "Ziba", "explanation": "Ziba, a servant of Saul''s household, was brought to David and pointed him to Mephibosheth. Machir of Lo-debar had been sheltering Mephibosheth, but it is Ziba whom David questions.", "book_code": "2SA", "chapter": 9, "reference": "2 Samuel 9:2-3", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "48532d53-96fd-af0c-27a0-9c44d281ccc6", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Ziba"], "stem_family": "characters|ziba", "difficulty_estimate": 630, "irt_b": 0.9, "importance_conceptual": 66, "importance_context": 72, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('95ae7855-f5ff-9fc0-f770-a7acf4867c0e'::uuid, 'batch18_characters_probe_shimei_curses_bahurim_mcq_v1', 'batch18|2SA|shimei_curses_bahurim', '{"prompt": "As David fled from Absalom, which man of Saul''s family came out of Bahurim yelling curses at him?", "choices": [{"id": "A", "text": "Shimei son of Gera the Benjamite"}, {"id": "B", "text": "Ziba the servant of Mephibosheth", "meta": {"distractor": {"plausibility": "high", "misconception_code": "man_met_on_the_same_road_just_before", "relation": "same_event"}}}, {"id": "C", "text": "Sheba son of Bichri the Benjamite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "other_benjamite_who_revolts_against_david", "relation": "same_book"}}}, {"id": "D", "text": "Mephibosheth son of Jonathan", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "sauls_heir_suspected_of_disloyalty", "relation": "same_event"}}}], "correct_choice_id": "A", "correct_answer": "Shimei son of Gera the Benjamite", "explanation": "Shimei son of Gera, of the house of Saul, cursed David at Bahurim. Ziba had met David with provisions a little earlier on the same road, and Sheba son of Bichri raises a separate Benjamite revolt afterwards.", "book_code": "2SA", "chapter": 16, "reference": "2 Samuel 16:5", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "95ae7855-f5ff-9fc0-f770-a7acf4867c0e", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Shimei"], "stem_family": "characters|shimei", "difficulty_estimate": 620, "irt_b": 0.85, "importance_conceptual": 70, "importance_context": 76, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('4efe4226-5d4b-9677-1194-7073b411fe60'::uuid, 'batch18_characters_probe_barzillai_mahanaim_mcq_v1', 'batch18|2SA|barzillai_mahanaim', '{"prompt": "Which aged Gileadite from Rogelim supplied David at Mahanaim and later escorted him over the Jordan?", "choices": [{"id": "A", "text": "Machir son of Ammiel", "meta": {"distractor": {"plausibility": "high", "misconception_code": "named_alongside_him_in_the_same_verse", "relation": "same_event"}}}, {"id": "B", "text": "Barzillai the Gileadite"}, {"id": "C", "text": "Shobi son of Nahash", "meta": {"distractor": {"plausibility": "high", "misconception_code": "named_alongside_him_in_the_same_verse", "relation": "same_event"}}}, {"id": "D", "text": "Ittai the Gittite", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "another_loyal_supporter_in_the_flight", "relation": "same_book"}}}], "correct_choice_id": "B", "correct_answer": "Barzillai the Gileadite", "explanation": "Three men met David at Mahanaim: Shobi, Machir, and Barzillai. Only Barzillai of Rogelim is the one who later came down to escort the king back across the Jordan.", "book_code": "2SA", "chapter": 17, "reference": "2 Samuel 17:27; 19:31", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "4efe4226-5d4b-9677-1194-7073b411fe60", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Barzillai"], "stem_family": "characters|barzillai", "difficulty_estimate": 700, "irt_b": 1.2, "importance_conceptual": 64, "importance_context": 70, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('61c2e099-a1b2-c7d3-7c98-637ac30c5ff7'::uuid, 'batch18_characters_probe_ittai_refuses_return_mcq_v1', 'batch18|2SA|ittai_refuses_return', '{"prompt": "Which foreigner did David tell to turn back because he was an exile, yet he insisted on going with the king?", "choices": [{"id": "A", "text": "Obed-edom the Gittite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_other_gittite_in_davids_story", "relation": "same_role"}}}, {"id": "B", "text": "Uriah the Hittite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "best_known_foreigner_in_davids_service", "relation": "same_role"}}}, {"id": "C", "text": "Ittai the Gittite"}, {"id": "D", "text": "Ahimelech the Hittite", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "another_foreign_soldier_with_david", "relation": "same_role"}}}], "correct_choice_id": "C", "correct_answer": "Ittai the Gittite", "explanation": "David urged Ittai the Gittite to go back and stay with the new king, since he was both a foreigner and an exile. Ittai swore to stay with David wherever he went.", "book_code": "2SA", "chapter": 15, "reference": "2 Samuel 15:19-22", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "61c2e099-a1b2-c7d3-7c98-637ac30c5ff7", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Ittai"], "stem_family": "characters|ittai", "difficulty_estimate": 680, "irt_b": 1.1, "importance_conceptual": 64, "importance_context": 70, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('ebf81752-2c5d-7da1-719a-2f71418bc9ee'::uuid, 'batch18_characters_probe_ahimaaz_runs_news_mcq_v1', 'batch18|2SA|ahimaaz_runs_news', '{"prompt": "Which son of Zadok begged Joab to let him run and carry the news after Absalom''s defeat?", "choices": [{"id": "A", "text": "Jonathan son of Abiathar", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_other_priests_son_who_ran_messages", "relation": "same_role"}}}, {"id": "B", "text": "the Cushite runner", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_man_joab_actually_sent_first", "relation": "same_event"}}}, {"id": "C", "text": "Joab son of Zeruiah", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "the_commander_who_refused_the_request", "relation": "same_event"}}}, {"id": "D", "text": "Ahimaaz son of Zadok"}], "correct_choice_id": "D", "correct_answer": "Ahimaaz son of Zadok", "explanation": "Ahimaaz son of Zadok pressed to run with the news. Joab first sent the Cushite instead, and only afterwards let Ahimaaz go, so that Ahimaaz outran him.", "book_code": "2SA", "chapter": 18, "reference": "2 Samuel 18:19-23", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "ebf81752-2c5d-7da1-719a-2f71418bc9ee", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Ahimaaz"], "stem_family": "characters|ahimaaz", "difficulty_estimate": 710, "irt_b": 1.25, "importance_conceptual": 62, "importance_context": 68, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('58cab59a-1f7a-8afa-6e2b-b2117df2b9f5'::uuid, 'batch18_characters_probe_amasa_absalom_commander_mcq_v1', 'batch18|2SA|amasa_absalom_commander', '{"prompt": "Whom did Absalom appoint over the army in place of Joab, and whom Joab later killed while greeting him?", "choices": [{"id": "A", "text": "Amasa"}, {"id": "B", "text": "Abishai", "meta": {"distractor": {"plausibility": "high", "misconception_code": "joabs_brother_and_fellow_commander", "relation": "same_role"}}}, {"id": "C", "text": "Ahithophel", "meta": {"distractor": {"plausibility": "high", "misconception_code": "absaloms_best_known_adviser", "relation": "same_event"}}}, {"id": "D", "text": "Sheba son of Bichri", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "the_rebel_amasa_was_sent_to_pursue", "relation": "same_book"}}}], "correct_choice_id": "A", "correct_answer": "Amasa", "explanation": "Absalom set Amasa over the army in Joab''s place. After the revolt, Joab took Amasa by the beard as if to kiss him and struck him down. Ahithophel was Absalom''s counsellor, not his general.", "book_code": "2SA", "chapter": 17, "reference": "2 Samuel 17:25; 20:9-10", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "58cab59a-1f7a-8afa-6e2b-b2117df2b9f5", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Amasa"], "stem_family": "characters|amasa", "difficulty_estimate": 690, "irt_b": 1.15, "importance_conceptual": 64, "importance_context": 70, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('d1d05aaf-dea4-6317-1a5f-7ef48bd3b867'::uuid, 'batch18_characters_probe_nahash_jabesh_gilead_mcq_v1', 'batch18|1SA|nahash_jabesh_gilead', '{"prompt": "Which Ammonite king laid siege to Jabesh-gilead, the crisis that launched Saul''s first victory?", "choices": [{"id": "A", "text": "Hanun the Ammonite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "his_son_who_fights_david_later", "relation": "same_generation"}}}, {"id": "B", "text": "Nahash the Ammonite"}, {"id": "C", "text": "Agag the Amalekite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_king_saul_spares_in_the_next_war", "relation": "same_role"}}}, {"id": "D", "text": "Achish king of Gath", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "philistine_king_of_the_same_era", "relation": "same_role"}}}], "correct_choice_id": "B", "correct_answer": "Nahash the Ammonite", "explanation": "Nahash the Ammonite besieged Jabesh-gilead and demanded the right eye of every man. The Spirit rushed on Saul and he delivered the city. Hanun, who humiliates David''s envoys, is Nahash''s son.", "book_code": "1SA", "chapter": 11, "reference": "1 Samuel 11:1", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "d1d05aaf-dea4-6317-1a5f-7ef48bd3b867", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Nahash"], "stem_family": "characters|nahash", "difficulty_estimate": 640, "irt_b": 0.95, "importance_conceptual": 68, "importance_context": 72, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('62f9227f-d6b2-220a-459c-71e33bbdb609'::uuid, 'batch18_characters_probe_hadadezer_zobah_mcq_v1', 'batch18|2SA|hadadezer_zobah', '{"prompt": "Which king of Zobah did David defeat as he marched to restore his dominion at the Euphrates?", "choices": [{"id": "A", "text": "Toi king of Hamath", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_king_who_congratulates_david_after", "relation": "same_event"}}}, {"id": "B", "text": "Rezin king of Aram", "meta": {"distractor": {"plausibility": "high", "misconception_code": "later_aramean_king_confused_for_him", "relation": "near_chronology"}}}, {"id": "C", "text": "Hadadezer son of Rehob"}, {"id": "D", "text": "Ben-hadad king of Aram", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "best_known_aramean_royal_name", "relation": "same_role"}}}], "correct_choice_id": "C", "correct_answer": "Hadadezer son of Rehob", "explanation": "David defeated Hadadezer son of Rehob, king of Zobah, at the Euphrates. Toi of Hamath, Hadadezer''s enemy, then sent his son to greet David. Rezin and Ben-hadad belong to later Aramean history.", "book_code": "2SA", "chapter": 8, "reference": "2 Samuel 8:3, 9", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "62f9227f-d6b2-220a-459c-71e33bbdb609", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Hadadezer", "Toi"], "stem_family": "characters|hadadezer", "difficulty_estimate": 720, "irt_b": 1.3, "importance_conceptual": 60, "importance_context": 66, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('18697ce5-edc7-383a-2438-eafd38e86d26'::uuid, 'batch18_characters_probe_abishag_shunammite_mcq_v1', 'batch18|1KI|abishag_shunammite', '{"prompt": "Which young Shunammite woman was sought throughout Israel to attend the aged King David?", "choices": [{"id": "A", "text": "Abigail the Carmelite", "meta": {"distractor": {"plausibility": "high", "misconception_code": "similar_name_and_davids_wife", "relation": "same_generation"}}}, {"id": "B", "text": "Ahinoam of Jezreel", "meta": {"distractor": {"plausibility": "high", "misconception_code": "davids_other_named_wife", "relation": "same_generation"}}}, {"id": "C", "text": "Bathsheba daughter of Eliam", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "the_queen_present_in_the_same_chapter", "relation": "same_event"}}}, {"id": "D", "text": "Abishag the Shunammite"}], "correct_choice_id": "D", "correct_answer": "Abishag the Shunammite", "explanation": "Servants searched all Israel for a beautiful girl and found Abishag the Shunammite, who cared for David in his old age. Adonijah''s later request for her is what costs him his life.", "book_code": "1KI", "chapter": 1, "reference": "1 Kings 1:3", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "18697ce5-edc7-383a-2438-eafd38e86d26", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Abishag"], "stem_family": "characters|abishag", "difficulty_estimate": 650, "irt_b": 1.0, "importance_conceptual": 62, "importance_context": 68, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
