  ('fda94e3e-eebf-5505-ab38-c7404138c327'::uuid, 'batch18_characters_probe_ahaziah_judah_jehu_mcq_v1', 'batch18|2KI|ahaziah_judah_jehu', '{"prompt": "Which king of Judah did Jehu''s men shoot on the Ascent of Gur, so that he fled to Megiddo and died there?", "choices": [{"id": "A", "text": "Joram son of Ahab", "meta": {"distractor": {"plausibility": "high", "misconception_code": "killed_by_jehu_in_the_same_episode", "relation": "same_event"}}}, {"id": "B", "text": "Ahaziah son of Jehoram"}, {"id": "C", "text": "Jehoram son of Jehoshaphat", "meta": {"distractor": {"plausibility": "high", "misconception_code": "his_father_confused_for_him", "relation": "same_generation"}}}, {"id": "D", "text": "Amaziah son of Joash", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "another_judahite_king_killed_in_flight", "relation": "same_role"}}}], "correct_choice_id": "B", "correct_answer": "Ahaziah son of Jehoram", "explanation": "Jehu killed Joram of Israel first, then pursued Ahaziah of Judah, son of Jehoram, who was shot near Ibleam and died at Megiddo. The near-identical royal names in the two kingdoms are the trap.", "book_code": "2KI", "chapter": 9, "reference": "2 Kings 8:25; 9:27", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "fda94e3e-eebf-5505-ab38-c7404138c327", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Ahaziah", "Jehoram", "Joram"], "stem_family": "characters|ahaziah", "difficulty_estimate": 750, "irt_b": 1.45, "importance_conceptual": 68, "importance_context": 72, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
  ('07774a8f-d362-6517-ccc7-3ba63ba5aaaf'::uuid, 'batch18_characters_probe_baasha_kills_nadab_mcq_v1', 'batch18|1KI|baasha_kills_nadab', '{"prompt": "Who conspired against Nadab at Gibbethon of the Philistines and took the throne of Israel?", "choices": [{"id": "A", "text": "Zimri commander of the chariots", "meta": {"distractor": {"plausibility": "high", "misconception_code": "the_next_usurper_at_the_same_place", "relation": "near_chronology"}}}, {"id": "B", "text": "Omri commander of the army", "meta": {"distractor": {"plausibility": "high", "misconception_code": "another_commander_who_seizes_the_throne", "relation": "near_chronology"}}}, {"id": "C", "text": "Baasha son of Ahijah"}, {"id": "D", "text": "Jehu son of Nimshi", "meta": {"distractor": {"plausibility": "medium", "misconception_code": "the_best_known_usurper_of_israel", "relation": "same_role"}}}], "correct_choice_id": "C", "correct_answer": "Baasha son of Ahijah", "explanation": "Baasha son of Ahijah struck down Nadab while Israel was besieging Gibbethon, and wiped out the house of Jeroboam. Gibbethon is also where Omri is later proclaimed king, which invites the confusion.", "book_code": "1KI", "chapter": 15, "reference": "1 Kings 15:27", "dimension_key": "characters_lineage", "dimension": "characters", "question_id": "07774a8f-d362-6517-ccc7-3ba63ba5aaaf", "question_layer": "bank_growth", "question_format": "standard", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Baasha"], "stem_family": "characters|baasha", "difficulty_estimate": 700, "irt_b": 1.2, "importance_conceptual": 66, "importance_context": 70, "position_rebalanced": true, "distractor_contract_version": 1, "distractor_quality_reviewed": true}'::jsonb),
