  ('541ed354-2f99-f700-fb8c-35ae9f984efe'::uuid, 'sequence_order_v1', 'batch18|2SA|absalom_flight_people', '{"prompt": "Place the men David met on his flight from Absalom in the order he met them.", "choices": [{"id": "ittai", "text": "Ittai the Gittite refuses to turn back"}, {"id": "ziba", "text": "Ziba meets David with loaded donkeys"}, {"id": "shimei", "text": "Shimei comes out of Bahurim cursing"}, {"id": "barzillai", "text": "Barzillai supplies the king at Mahanaim"}], "correct_order": ["ittai", "ziba", "shimei", "barzillai"], "correct_choice_id": "ittai", "correct_answer": "Ittai the Gittite refuses to turn back -> Ziba meets David with loaded donkeys -> Shimei comes out of Bahurim cursing -> Barzillai supplies the king at Mahanaim", "explanation": "Ittai pledges loyalty as the column leaves Jerusalem; Ziba meets David just beyond the summit; Shimei curses him at Bahurim further on; Barzillai provisions him once he reaches Mahanaim.", "book_code": "2SA", "chapter": 15, "reference": "2 Samuel 15:19; 16:1; 16:5; 17:27", "dimension_key": "events_timeline", "dimension": "events", "question_id": "541ed354-2f99-f700-fb8c-35ae9f984efe", "question_layer": "bank_growth", "question_format": "sequence_order", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Ittai", "Ziba", "Shimei", "Barzillai"], "stem_family": "sequence|2SA|absalom_flight_people", "difficulty_estimate": 740, "irt_b": 1.4, "importance_conceptual": 68, "importance_context": 74, "baseline_eligible": false, "length_tell_reviewed": true, "length_tell_exception_reason": "order_response_has_no_single_correct_option"}'::jsonb),
  ('3d46cbcd-3f16-db76-4a2a-08730f7f5bd2'::uuid, 'sequence_order_v1', 'batch18|1KI|israel_kings_baasha_omri', '{"prompt": "Place these kings of Israel in the order they came to the throne.", "choices": [{"id": "baasha", "text": "Baasha, who struck down Nadab"}, {"id": "elah", "text": "Elah, the son of Baasha"}, {"id": "zimri", "text": "Zimri, who reigned seven days"}, {"id": "omri", "text": "Omri, the commander of the army"}], "correct_order": ["baasha", "elah", "zimri", "omri"], "correct_choice_id": "baasha", "correct_answer": "Baasha, who struck down Nadab -> Elah, the son of Baasha -> Zimri, who reigned seven days -> Omri, the commander of the army", "explanation": "Baasha seized the throne by killing Nadab, his son Elah followed, Zimri assassinated Elah and held Tirzah seven days, and the army then proclaimed Omri, who founded the dynasty of Ahab.", "book_code": "1KI", "chapter": 16, "reference": "1 Kings 15:27; 16:8, 15, 23", "dimension_key": "events_timeline", "dimension": "events", "question_id": "3d46cbcd-3f16-db76-4a2a-08730f7f5bd2", "question_layer": "bank_growth", "question_format": "sequence_order", "source_batch": "20260906_batch18_person_coverage", "coverage_targets": ["Baasha", "Elah", "Zimri"], "stem_family": "sequence|1KI|israel_kings_baasha_omri", "difficulty_estimate": 760, "irt_b": 1.5, "importance_conceptual": 66, "importance_context": 72, "baseline_eligible": false, "length_tell_reviewed": true, "length_tell_exception_reason": "order_response_has_no_single_correct_option"}'::jsonb),
